INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-6BrwJMOO3fE', 'राजुरी अपघातानंतर देवराम लांडे आक्रमक! थेट आळेफाटा पोलीस ठाण्यावर मोर्चा ! नक्की काय झाले?', NULL, '<p>कल्याण-अहिल्यानगर महामार्गावरील राजुरी येथे झालेल्या भीषण अपघातात दुचाकीस्वार राजू साहेबराव मुठे यांचा दुर्दैवी मृत्यू झाला, तर त्यांची पत्नी जाईबाई मुठे गंभीर जखमी झाल्या आहेत.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-rV03IkxC0qI', 'कुणाच्या बापाचा बाप आला तरी प्रकल्प होऊ देणार नाही! अतुल बेनकेंचा इशारा | वृक्षतोडीविरोधात आंदोलन', NULL, '<p>कर्जत –भीमाशंकर परिसरातील प्रस्तावित प्रकल्प आणि वृक्षतोडीच्या मुद्द्यावरून आता वातावरण तापू लागले आहे. निसर्ग, जंगल आणि वन्यजीवांचे संरक्षण करण्यासाठी स्थानिक नागरिकांनी एकत्र येत वृक्षतोडीविरोधात आंदोलनाची भूमिका घेतली आहे.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-vpvCS8eAOF0', 'वडगाव आनंद सोसायटीचा सभासदांना दिवाळीचा गोडवा! ज्येष्ठ सभासदांच्या हस्ते भेटवस्तू वाटप', NULL, '<p>दिवाळीचा आनंद द्विगुणित करण्यासाठी वडगाव आनंद विविध कार्यकारी सहकारी सेवा सोसायटीच्या वतीने सभासदांसाठी दिवाळी भेटवस्तू वाटप समारंभाचे आयोजन करण्यात आले.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-3drByQU2t70', 'दारूच्या ट्रकला आग लागण्याचं कारण काय? घटनेने आळेखिंड परिसरात खळबळ', NULL, '<p>आळेखिंड परिसरात दारूची वाहतूक करणाऱ्या ट्रकला अचानक आग लागल्याची घटना समोर आली आहे. ट्रकला आग लागल्यानंतर घटनास्थळी धावपळ उडाली. आगीच्या ज्वाळा आणि धुरामुळे परिसरातील नागरिकांचे लक्ष या घटनेकडे वेधले गेले.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-KNsSz-Z8tmo', 'अखेर आळेफाटा बस स्थानकातील ते अनधिकृत गाळे हटवले', NULL, '<p>आळेफाटा बसस्थानक परिसरातील अनधिकृत गाळ्यांवर अखेर कारवाई करण्यात आली आहे. जेसीबीच्या सहाय्याने गाळे हटविण्याची कारवाई करण्यात आली असून, यामुळे बसस्थानक परिसरातील अतिक्रमणाचा प्रश्न पुन्हा चर्चेत आला आहे.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-NWUBhK6wTV0', 'चारा महागला, दुष्काळ वाढला… तरी गायींचे दर स्थिर ! आळेफाटा बाजारात नेमकं काय घडतंय ?', NULL, '<p>दुष्काळी परिस्थिती, चारा-पाण्याचा प्रश्न आणि जनावरांच्या संगोपनासाठी वाढणारा खर्च… अशा परिस्थितीत आळेफाटा गाय बाजारातील गायींच्या बाजारभावात अपेक्षित वाढ होताना दिसत नाही.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-N7tlSopgy_8', 'कर्जत-भीमाशंकर प्रकल्पाला विरोध का? सुरज वाजगेंनी सांगितली जंगलतोडीमागची भीती!', NULL, '<p>कर्जत-भीमाशंकर प्रकल्पाला विरोध का? जंगलतोडीमागची भीती काय? | सुरज वाजगे यांची स्पष्ट भूमिका</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-cqJsz0mBsac', 'जंगलतोडीविरोधात एल्गार! आळेफाट्यात तरुण एकवटले!उद्या तहसीलदारांना निवेदन; रस्ता रोको होणार?', NULL, '<p>कर्जत-भीमाशंकर परिसरात सुरू असलेल्या वृक्षतोडीच्या मुद्द्यावरून आळेफाटा येथे तरुण एकवटले आहेत. जंगल, वन्यजीव आणि पर्यावरणाच्या संरक्षणासाठी तरुणांनी पुढाकार घेतला असून, या संदर्भात उद्या तहसीलदारांना निवेदन देण्यात येणार आहे.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-XPOEmCVpmPw', 'गायींचे दर कोसळलेच! शेतकरी संकटात; आळेफाटा गाय बाजारात दर घसरलेलेच! शेतकरी हतबल', NULL, '<p>आळेफाटा गाय बाजारात गायींचे दर कोसळले! शेतकरी संकटात; बाजारात मंदीचे सावट</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-BAbKgERrXvI', 'आळेफाटा येथे राष्ट्रीय स्वयंसेवक संघाचे (RSS) पथसंचलन! नेमका काय आहे उद्देश?', NULL, '<p>आळेफाटा येथे आज राष्ट्रीय स्वयंसेवक संघाच्या (RSS) वतीने पथसंचलन करण्यात आले. पांढरा शर्ट, खाकी पँट आणि काळी टोपी परिधान केलेल्या स्वयंसेवकांनी शिस्तबद्ध पद्धतीने संचलनात सहभाग घेतला. ढोलवादनाच्या गजरात पार पडलेल्या या पथसंचलनाची खास दृश्ये या व्हिडिओमध्ये पाहायला मिळतील.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-SuvabEbepiE', 'नऊ देवींची नऊ रूपं… नैवेद्य काय आणि फलश्रुती काय? ह.भ.प. कार्तिक महाराज काकडे', NULL, '<p>नवरात्रीमध्ये नऊ दिवस कोणत्या देवीची पूजा केली जाते? प्रत्येक देवीला कोणता नैवेद्य दाखवावा? त्या नैवेद्याचे धार्मिक महत्त्व काय आहे आणि नऊ देवींची फलश्रुती काय सांगितली आहे? या सर्व प्रश्नांची माहिती जाणून घ्या ह.भ.प. कार्तिक महाराज काकडे यांच्या मार्गदर्शनातून!</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-QEmYGe7avL4', 'एक लाखाची गाय ६५ हजारांत! आळेफाटा गाय बाजारात नेमकं काय घडलं?', NULL, '<p>दुष्काळी परिस्थितीचा फटका आता गाय बाजारालाही बसू लागला आहे. कृषी उत्पन्न बाजार समिती, जुन्नरच्या आळेफाटा उपबाजारात गायींच्या किमतीत मोठी घसरण झाली आहे. एक लाख रुपयांपर्यंत किंमत असलेली गाय आता ६५ ते ७० हजार रुपयांना, तर ३० ते ३५ हजारांची गाय अवघ्या १४ ते १५ हजार रुपयांना विकली जात असल्याचे चित्र आहे.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-f0HH48gNx8c', '“मी तुला ओळखत नाही!” मुलीच्या एका वाक्याने हरलेला बाप… | वसंत हंकारे सर यांच्याशी खास मुलाखत', NULL, '<p>“मी तुला ओळखत नाही!” मुलीच्या एका वाक्याने हरलेला बाप… | वसंत हंकारे सर | खास मुलाखत</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-KhbFLBxb19s', 'वाढदिवसाचा खर्च टाळत डॉ. संजय गाडेकरांचा सेवाभावी उपक्रम; रस्त्यावरील खड्डे बुजवले!', NULL, '<p>वाढदिवसाचा अनावश्यक खर्च टाळत डॉ. संजय गाडेकर यांनी सेवाभावी उपक्रम राबवला. वाढदिवसानिमित्त रस्त्यावर पडलेल्या खड्ड्यांमध्ये मुरूम टाकून ते बुजवण्यात आले.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-5q_lj2Topn0', 'वडगाव आनंद येथे तुळजाभवानी मातेच्या पालखीचे आगमन; भक्तिमय वातावरणात भाविकांनी केले स्वागत', NULL, '<p>वडगाव आनंद येथे तुळजाभवानी मातेच्या पालखीचे भक्तिमय वातावरणात आगमन झाले. फुलांनी आकर्षक सजविण्यात आलेल्या पालखीचे ग्रामस्थ व भाविकांनी उत्साहात स्वागत केले. यावेळी परिसरात भक्तिमय वातावरण निर्माण झाले होते.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-Oo5SWBJuAfI', 'आळेफाटा पोलिसांच्या गणपतीची विसर्जन मिरवणूक उत्साहात; धरला पारंपरिक वाद्यांच्या ठेक्यावर ठेका', NULL, '<p>आळेफाटा पोलिसांनी बसवलेल्या श्री गणपती बाप्पाच्या विसर्जनाची मिरवणूक उत्साहात पार पडली.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-6SusKxgXShE', 'सुवर्ण महोत्सवानिमित्त श्री गणेश कथा महायज्ञाचे आयोजन पर्यावरणपूरक गणेशोत्सवात जपली परंपरा संस्कृती', NULL, '<p>श्री सन्मित्र मित्र मंडळाचा सुवर्ण महोत्सव</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-Qz2SM82Je54', 'वाटाण्याच्या कॅप्टन व्हरायटीने बदलले शेतीचे गणित! | उंब्रजचे शेतकरी गणेश हांडे यांच्याशी खास बातचीत', NULL, '<p>उंब्रज येथील शेतकरी गणेश हांडे यांच्याशी कॅप्टन व्हरायटीच्या वाटाणा पिकाबाबत घेतलेली थेट मुलाखत. या ग्राउंड रिपोर्टमध्ये कॅप्टन व्हरायटीची लागवड, पिकाचा अनुभव, उत्पादन, शेतकऱ्यांना मिळणारे फायदे आणि शेतीतील प्रत्यक्ष अनुभव जाणून घेणार आहोत.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-C38VP6dS9uc', 'वडगाव आनंदमध्ये अंड्यांच्या दुर्गंधीने नागरिक हैराण! आरोग्य धोक्यात', NULL, '<p>वडगाव आनंद येथील चासकर मळा परिसरात अंडी व्यवसायाशी संबंधित ठिकाणी अंडी अस्ताव्यस्त पद्धतीने ठेवण्यात आल्याचा आरोप नागरिकांकडून केला जात आहे. खराब अंड्यांमुळे परिसरात उग्र दुर्गंधी पसरत असून नागरिकांना मोठ्या त्रासाला सामोरे जावे लागत असल्याचे सांगितले जात आहे.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-bPk0OA8wd88', 'शेतजमिनी वाचवा! कल्याण–लातूर महामार्गाविरोधात माळवाडीचे शेतकरी आक्रमक; आंदोलनाचा इशारा!', NULL, '<p>“शेतजमिनी वाचवा!” या मागणीसाठी कल्याण–लातूर जनकल्याण महामार्गाविरोधात माळवाडीतील शेतकरी आक्रमक झाले आहेत. प्रस्तावित महामार्गामुळे मोठ्या प्रमाणावर शेतजमिनी बाधित होण्याची शक्यता असून, शेतकऱ्यांनी महामार्गाचा मार्ग बदलण्याची मागणी केली आहे.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-aedmmpRxzCg', 'बिहारहून १२ ज्योतिर्लिंग व चारधाम यात्रेला निघालेला ‘मोनू उर्फ ब्लॅक पॅंथर’ शिवजन्मभूमीत!', NULL, '<p>बिहारहून १२ ज्योतिर्लिंग आणि चारधाम यात्रेसाठी निघालेला मोनू उर्फ ‘ब्लॅक पॅंथर’ यांचे शिवजन्मभूमीत उत्साहात स्वागत करण्यात आले.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-13RA4fLHrn0', 'पिंपळवंडीतील पीडित कुटुंबाच्या भेटीला सुनेत्रा पवार; घरकुल, १० लाख मदत अन् शिक्षणाची जबाबदारी घेणार', NULL, '<p>पिंपळवंडी चिमुकली हत्या प्रकरणात पीडित कुटुंबाची सुनेत्रा पवार यांनी भेट घेऊन सांत्वन केले. यावेळी पीडित कुटुंबाला धीर देत त्यांच्या घरकुलासाठी आवश्यक ती तरतूद करण्याचे आश्वासन देण्यात आले. तसेच मनोधैर्य योजनेतून १० लाख रुपयांची मदत देण्याबाबत आणि पीडित मुलीच्या भावंडांच्या शिक्षणाची जबाबदारी शासनाकडून घेण्यात येईल, असे आश्वासन देण्यात आले.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-v9KxJKCVbHE', 'तुषार वामन यांच्या वक्तव्यावर आनंद रासकर भडकले म्हणाले पिंपळवंडी बापच होती बापच आहे आणी बापच राहणार', NULL, '<p>पिंपळवंडी बापच होती, बापच आहे आणि बापच राहणार! – आनंद रासकर</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-VuMGGoW7Iz8', 'पीडित कुटुंबाला न्याय मिळवून देण्यासाठी आ. डॉ. नीलम गोऱ्हे यांचा पुढाकार पिंपळवंडीतील पत्रकार परिषद', NULL, '<p>पिंपळवंडी येथील प्रकरणातील पीडित कुटुंबाला न्याय मिळवून देण्यासाठी आ. डॉ. नीलम गोऱ्हे यांनी पुढाकार घेतला आहे. यासंदर्भात त्यांनी पिंपळवंडी येथे पत्रकार परिषद घेऊन प्रकरणाबाबत आपली भूमिका मांडली.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-pJSMAB8dFvo', 'पिंपळवंडी प्रकरणात आ.डॉ.नीलम गोऱ्हेंची पोलीस अधिकाऱ्यांशी चर्चा पीडित कुटुंबीयांची भेट घेऊन सांत्वन', NULL, '<p>पिंपळवंडी येथील अत्याचार प्रकरणाच्या पार्श्वभूमीवर आ. डॉ. नीलम गोऱ्हे यांनी पोलीस अधिकाऱ्यांची भेट घेऊन तपासाबाबत सविस्तर माहिती घेतली. यावेळी त्यांनी पीडित मुलीच्या कुटुंबीयांची भेट घेऊन त्यांचे सांत्वन केले व त्यांच्याशी संवाद साधला.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-OACvtra_0Hw', 'पिंपळवंडी प्रकरणावर आळेफाट्यात संताप! महिला दक्षता समितीने SP संदीप सिंह गिल यांना दिले निवेदन', NULL, '<p>पिंपळवंडी येथील घटनेच्या निषेधार्थ आळेफाट्यात संताप व्यक्त करण्यात आला. आळेफाटा महिला दक्षता समिती व भाजप युवा मोर्चा युवा महिला आघाडी जुन्नर तालुकाच्या पदाधिकारी व सदस्यांनी आळेफाटा पोलीस स्टेशन येथे पोलीस अधीक्षक संदीप सिंह गिल यांची भेट घेतली.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-OqTJX8Emz9o', 'पिंपळवंडी हादरली! चिमुकलीवरील अत्याचार प्रकरणाची Ground Report; आरोपी ताब्यात, नागरिकांचा आक्रोश', NULL, '<p>पिंपळवंडी परिसराला हादरवून सोडणाऱ्या चिमुकलीवरील अत्याचाराच्या गंभीर प्रकरणाची Ground Report या व्हिडिओमध्ये पाहा. आरोपीला पोलिसांनी ताब्यात घेतल्यानंतर नागरिकांमध्ये संतापाची लाट उसळली असून, न्यायासाठी नागरिकांनी आक्रोश व्यक्त केला आहे.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-cW0nOuV-q9k', 'पिंपळवंडीत चिमुकलीवरील अत्याचाराने संताप! न्यायासाठी नागरिक रस्त्यावर पुणे-नाशिक महामार्ग रोखला', NULL, '<p>पिंपळवंडी येथे १० वर्षीय चिमुकलीवर अत्याचार करून तिची हत्या झाल्याच्या घटनेने परिसरात संतापाची लाट उसळली आहे. या घटनेच्या निषेधार्थ आणि पीडित कुटुंबाला न्याय मिळावा, आरोपीला कठोरात कठोर शिक्षा व्हावी, या मागणीसाठी नागरिक मोठ्या संख्येने रस्त्यावर उतरले.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-5X9NmMOgnGA', 'नागपंचमीला सापांना दूध पाजावे का? सर्पमित्र आकाश माळी यांनी सांगितले सत्य', NULL, '<p>श्रावण, नागपंचमी आणि साप — सर्पमित्र आकाश माळी यांची विशेष मुलाखत</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-bkv8X8hzBxk', 'राष्ट्रपतींच्या हस्ते मिळाले पोलीस पदक! श्वान प्रशिक्षक गेनभाऊ भुजबळांचा थक्क करणारा प्रवास', NULL, '<p>१५ ऑगस्ट विशेष | राष्ट्रपती पोलीस पदक विजेते गेनभाऊ कृष्णाजी भुजबळ यांची प्रेरणादायी कहाणी</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-dtSujgND1I8', 'आळेफाटा येथे पोलीस भरती प्रशिक्षणार्थी भाग्यश्री भंडारीची गळफास घेऊन आत्महत्या', NULL, '<p>आळेफाटा येथे पोलीस भरती प्रशिक्षण घेणाऱ्या भाग्यश्री भास्कर भंडारी (वय 23) हिच्या आत्महत्येने परिसरात खळबळ उडाली आहे.</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-Yr6C0mRCIYk', 'वडगाव कांदळीत ३५० नागरिकांना एसटी स्मार्ट कार्ड ! ग्रामस्थांचा उत्स्फूर्त प्रतिसाद', NULL, '<p>वडगाव कांदळीत ३५० नागरिकांना एसटी स्मार्ट कार्ड! ग्रामस्थांचा उत्स्फूर्त प्रतिसाद आदर्श निर्मल ग्राम वडगाव (कांदळी), ता. जुन्नर येथे सामाजिक कार्यकर्त्या सौ. शोभाताई पाचपुते यांच्या आयोजनाखाली शिक्षण व सामाजिक विकास फाउंडेशनच्या वतीने एसटी NCMC स्मार्ट कार्ड शिबिर व कार्ड प्रदान सोहळा आयोजित करण्यात आला. गावातील ज्येष्ठ नागरिक, महिला, शालेय विद्यार्थी आणि इतर ग्रामस्थांना एसटी स्मार्ट कार्डचा लाभ मिळावा, या उद्देशाने आयोजित केलेल्या शिबिराला परिसरातील नागरिकांचा उत्स्फूर्त प्रतिसाद मिळाला. या शिबिरात जवळपास ३५० नागरिकांनी नावनोंदणी करून योजनेचा लाभ घेतला. ऑनलाइन नोंदणी केलेल्या लाभार्थ्यांना मारुती मंदिर हॉल, वडगाव कांदळी येथे मान्यवरांच्या हस्ते स्मार्ट कार्ड प्रदान करण्यात आले. यावेळी एसटी महामंडळाचे अधिकारी, पंचायत सदस्या सौ. माधुरीताई निलख, ग्रामपंचायत सदस्या रेश्मा फुलवडे, अहमद सय्यद, ज्येष्ठ मार्गदर्शक आर. डी. पाचपुते यांच्यासह गावातील प्रमुख पदाधिकारी व ग्रामस्थ उपस्थित होते. एसटी स्मार्ट कार्डचे फायदे, रिचार्ज करण्याची पद्धत आणि कार्डचा वापर याबाबतही नागरिकांना मार्गदर्शन करण्यात आले. या उपक्रमामुळे ग्रामस्थांचा वेळ, प्रवासाचा त्रास आणि खर्च वाचण्यास मदत होणार आहे.</p>', (SELECT id FROM categories WHERE slug = 'social'), 'वडगाव कांदळी', 'NEWS24 SHIVNERI प्रतिनिधी', 'NEWS24 SHIVNERI (व्हिडिओ वृत्त)', 'Yr6C0mRCIYk', 0, 0, 'published', '2026-08-10T10:29:31Z', '2026-08-10T10:29:31Z', '2026-08-10T10:29:31Z') ON CONFLICT(slug) DO NOTHING;
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-b7DltFAdPkM', 'पुणे–नाशिक सरळ रेल्वेमार्गाच्या मागणीसाठी आळेफाटा येथे रास्ता रोको आंदोलन; पावसातही उत्स्फूर्त सहभाग', NULL, '<p>रेल्वे सरळ मार्गे जावी यासाठी आळेफाटा येथे रास्ता रोको! पुणे–नाशिक सरळ रेल्वेमार्ग आळेफाटामार्गे व्हावा, या प्रमुख मागणीसाठी क्रांती दिनानिमित्त आळेफाटा येथे रास्ता रोको आंदोलन करण्यात आले. पावसाची पर्वा न करता नागरिक, विविध पक्षांचे पदाधिकारी, कार्यकर्ते आणि रेल्वे मार्गासाठी लढणारे आंदोलनकर्ते मोठ्या संख्येने रस्त्यावर उतरले. पुणे–नाशिक रेल्वेचा सरळ मार्ग आळेफाटा, नारायणगाव, मंचर, खेड, चाकणमार्गे व्हावा, अशी मागणी यावेळी करण्यात आली. या आंदोलनातून शासनाचे लक्ष वेधून घेत पुणे–नाशिक सरळ रेल्वेमार्गाचा प्रश्न तातडीने मार्गी लावावा, अशी जोरदार मागणी करण्यात आली. क्रांती दिन – ९ ऑगस्ट</p>', (SELECT id FROM categories WHERE slug = 'politics'), 'आळेफाटा', 'NEWS24 SHIVNERI प्रतिनिधी', 'NEWS24 SHIVNERI (व्हिडिओ वृत्त)', 'b7DltFAdPkM', 0, 0, 'published', '2026-08-09T05:29:38Z', '2026-08-09T05:29:38Z', '2026-08-09T05:29:38Z') ON CONFLICT(slug) DO NOTHING;
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-oZNM1-oB0t0', '९ ऑगस्टला आळेफाट्यात महामार्गावर चक्काजाम! पुणे-नाशिक सरळ रेल्वेमार्गासाठी जनआंदोलन,मोठी बातमी', NULL, '<p>९ ऑगस्टला आळेफाट्यात महामार्गावर चक्काजाम! | पुणे-नाशिक सरळ रेल्वेमार्गासाठी जनआंदोलन</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-RbsHDjJ3XDI', 'आळे,आळेफाटा ते वडगाव आनंद सिमेंट काँक्रीट रस्त्याचे काम का होत नाही? जाणून घ्या नेमके काय कारण!', NULL, '<p>अहिल्यानगर–कल्याण महामार्गावरील आळे, आळेफाटा ते वडगाव आनंद या महत्त्वाच्या मार्गावर सिमेंट काँक्रीट रस्त्याचे काम अद्याप पूर्ण का झाले नाही? काम नेमके कोणत्या टप्प्यावर आहे? निधी, प्रशासकीय प्रक्रिया, तांत्रिक अडचणी की अन्य काही कारणे यामुळे हा प्रकल्प रखडला आहे का?</p>
INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-FH_73ucLmQ0', 'आळेफाट्यात संत सावता महाराज पुण्यतिथीनिमित्त भक्तीचा महोत्सव; ५ ते १२ ऑगस्ट २०२६ अखंड हरिनाम सप्ताह', NULL, '<p>श्री संत शिरोमणी सावता महाराज व संत नामदेव महाराज यांच्या समाधी सोहळा व पुण्यतिथीनिमित्त दि. ५ ते १२ ऑगस्ट २०२६ या कालावधीत अखंड हरिनाम सप्ताह व श्री दासबोध पारायण सोहळ्याचे भव्य आयोजन करण्यात आले आहे.</p>
