INSERT INTO articles (slug, headline, subtitle, body_html, category_id, location_label, byline, source, youtube_id, is_featured, is_breaking, status, published_at, created_at, updated_at) VALUES ('yt-iIsHpvNL39I', 'वडगाव आनंदच्या उपसरपंचपदी संतोष पादीर यांची बिनविरोध निवड,ग्रामस्थांकडून सत्कार,पाहिली प्रतिक्रिया', NULL, '<p>वडगाव आनंद ग्रामपंचायतीच्या उपसरपंचपदी संतोष पादीर यांची बिनविरोध निवड! वडगाव आनंद (ता. जुन्नर) ग्रामपंचायतीच्या उपसरपंचपदी संतोष पादीर यांची बिनविरोध निवड करण्यात आली. मावळते उपसरपंच गणेश भुजबळ यांच्या राजीनाम्यानंतर झालेल्या निवड प्रक्रियेत त्यांची एकमताने निवड झाली. निवडीनंतर ग्रामस्थांच्या वतीने त्यांचा शाल, श्रीफळ व पुष्पगुच्छ देऊन सत्कार करण्यात आला. या कार्यक्रमाला सरपंच, ग्रामपंचायत सदस्य, ग्रामविकास अधिकारी, ग्रामपंचायत कर्मचारी तसेच गावातील विविध क्षेत्रांतील मान्यवर व ग्रामस्थ मोठ्या संख्येने उपस्थित होते.</p>', (SELECT id FROM categories WHERE slug = 'politics'), 'वडगाव आनंद', 'NEWS24 SHIVNERI प्रतिनिधी', 'NEWS24 SHIVNERI (व्हिडिओ वृत्त)', 'iIsHpvNL39I', 0, 0, 'published', '2026-07-10T10:57:21Z', '2026-07-10T10:57:21Z', '2026-07-10T10:57:21Z') ON CONFLICT(slug) DO NOTHING;
